INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张雄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张雄。", "biography": null, "status": "draft", "id": "c143e925-2fd8-5be6-abed-b89d550f0724"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "吕用之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的吕用之，在此段中为被指控者。", "biography": null, "status": "draft", "id": "cd08ae2a-9825-5636-a942-312bb29aed61"}, {"name": "高骈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的高骈，在此段中为受呈者。", "biography": null, "status": "draft", "id": "c4d5b35a-b520-57df-87da-baff9480b7e4"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "袁袭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：袁袭。", "biography": null, "status": "draft", "id": "d95b1977-3071-5079-81f5-f8c167f38c71"}, {"name": "孙端", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：孙端。", "biography": null, "status": "draft", "id": "2b072250-32cd-5a02-96f4-c07057dec132"}, {"name": "郑汉章", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：郑汉章。", "biography": null, "status": "draft", "id": "6627883e-83a2-5c78-b77d-a62093d2195c"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "张晊", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：张晊。", "biography": null, "status": "draft", "id": "4c26e1dc-5a81-51f0-b046-cee75fe25e88"}, {"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的秦宗权，在此段中为遣兵者。", "biography": null, "status": "draft", "id": "4ab9b100-f137-522e-9b11-1ef372de9edf"}, {"name": "张神剑（高邮）", "aliases": ["张神剑"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张神剑（高邮）。", "biography": null, "status": "draft", "id": "d6d78194-79d3-5a9c-87dd-21fc50ffd8c1"}, {"name": "毕师铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：毕师铎。", "biography": null, "status": "draft", "id": "f1541150-4966-5c04-9879-060cf391f2c2"}, {"name": "高霸", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：高霸。", "biography": null, "status": "draft", "id": "64514634-2a39-5304-9e5c-ffda4859587b"}, {"name": "刘金", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：刘金。", "biography": null, "status": "draft", "id": "f52d5f3e-f0ed-5141-b2d1-7c46f0142156"}, {"name": "贾令威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：贾令威。", "biography": null, "status": "draft", "id": "6f86101f-e1ad-506c-86a5-01572a3af3a6"}, {"name": "朱瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑄。", "biography": null, "status": "draft", "id": "dcaf5869-c45e-5845-b02f-6418dd1f22eb"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9