INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "张雄屯东塘并遣赵晖据上元", "start_year": 887, "end_year": 887, "time_original": "光启三年五月前后；具体日未载", "dynasty": "唐", "description": "前苏州刺史张雄率众溯江屯东塘，遣赵晖据上元。", "phases": [], "location_name": "东塘、上元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "442c33dd-1ae5-59eb-ba11-171f44ced552"}, {"title": "吕用之伪造高骈牒召杨行密", "start_year": 887, "end_year": 887, "time_original": "毕师铎攻广陵时；具体日未载", "dynasty": "唐", "description": "吕用之伪造高骈公文，署杨行密为行军司马，要求杨行密率兵入援。", "phases": [], "location_name": "广陵、庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8959b408-5e80-5ad9-8c6b-8ed9c3faacdc"}, {"title": "袁袭劝杨行密赴淮南", "start_year": 887, "end_year": 887, "time_original": "毕师铎攻广陵时；具体日未载", "dynasty": "唐", "description": "庐江人袁袭劝杨行密趁淮南各方冲突率兵前往；杨行密采纳。", "phases": [], "location_name": "庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "af99e9fa-0f9e-5d86-b175-8644d2950e3a"}, {"title": "杨行密合兵抵天长", "start_year": 887, "end_year": 887, "time_original": "光启三年五月", "dynasty": "唐", "description": "杨行密发庐州兵，又向和州刺史孙端借兵，合军抵天长。", "phases": [], "location_name": "庐州、和州、天长", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5ad2d1af-fb03-5348-b19e-ce450b2f34fa"}, {"title": "吕用之攻淮口未克后归杨行密", "start_year": 887, "end_year": 887, "time_original": "光启三年五月前后", "dynasty": "唐", "description": "郑汉章随毕师铎时留妻守淮口；吕用之攻十日未克，郑汉章率兵救援。吕用之闻杨行密抵天长，率众归附。", "phases": [], "location_name": "淮口、天长", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3db49f9a-175a-5efc-9505-cc47b408d059"}, {"title": "朱全忠再次击败张晊", "start_year": 887, "end_year": 887, "time_original": "光启三年五月丙子", "dynasty": "唐", "description": "朱全忠出兵击败张晊；秦宗权闻讯从郑州率精兵前来会合。", "phases": [], "location_name": "汴州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4b221af7-592f-5400-9c58-4fbbd84b0f0e"}, {"title": "张神剑率众归杨行密", "start_year": 887, "end_year": 887, "time_original": "光启三年五月；具体日未载", "dynasty": "唐", "description": "张神剑向毕师铎索取财货未获立即答应，遂率众归杨行密，并运高邮粮供其军。", "phases": [], "location_name": "高邮、天长方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "acb54241-7393-5da2-84fc-5daffa8512c6"}, {"title": "高霸等率众归杨行密", "start_year": 887, "end_year": 887, "time_original": "光启三年五月；具体日未载", "dynasty": "唐", "description": "高霸、刘金、贾令威各率众归杨行密，杨行密军势扩大。", "phases": [], "location_name": "海陵、曲溪、盱胎", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "977afe2e-a78c-55cb-a6d6-19453bbe1644"}, {"title": "朱全忠向兖郓及义成求援", "start_year": 887, "end_year": 887, "time_original": "光启三年五月辛巳前", "dynasty": "唐", "description": "朱全忠向兖、郓求援，朱瑄、朱瑾率兵来援，义成军也加入。", "phases": [], "location_name": "兖州、郓州、汴州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6b2bd92b-19d1-5cf3-8200-f5823c5a21d1"}, {"title": "朱全忠等在边孝村败秦宗权", "start_year": 887, "end_year": 887, "time_original": "光启三年五月辛巳", "dynasty": "唐", "description": "朱全忠率四镇兵攻秦宗权于边孝村，秦宗权败而夜遁；朱全忠追至阳武桥后返。", "phases": [], "location_name": "边孝村、阳武桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "55bb14de-0c3a-5a96-a90d-9c111940dfe9"}, {"title": "朱全忠兄事朱瑄", "start_year": 887, "end_year": 887, "time_original": "边孝村之战后", "dynasty": "唐", "description": "朱全忠感念朱瑄援军，以兄长之礼对待朱瑄。", "phases": [], "location_name": "汴州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "63e5d70f-1d55-5cd9-aba6-b5a824d7642f"}, {"title": "蔡军弃东都等驻地", "start_year": 887, "end_year": 887, "time_original": "秦宗权边孝村败后", "dynasty": "唐", "description": "蔡军在东都、河阳等地的驻军闻秦宗权败而撤离；秦宗权离郑州、孙儒离河阳时杀掠焚毁当地。", "phases": [], "location_name": "东都、河阳、许、汝、怀、郑、陕、虢", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fd862471-c953-52f1-83fc-8a18314fa82e"}, {"title": "许郑两州分别任命主事者", "start_year": 887, "end_year": 887, "time_original": "秦宗权边孝村败后", "dynasty": "唐", "description": "朝廷任杨守宗知许州事，朱全忠任孙从益知郑州事。", "phases": [], "location_name": "许州、郑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7f5c13a5-8f12-5eaf-8f62-d970e918e1a1"}, {"title": "钱镠遣将讨薛朗", "start_year": 887, "end_year": 887, "time_original": "光启三年五月；具体日未载", "dynasty": "唐", "description": "钱镠遣杜稜、阮结、成及率兵讨薛朗。", "phases": [], "location_name": "东安、浙江、静江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "08078ac8-a301-5fc7-b9ac-28fa564122b4"}, {"title": "赵晖于上元截击秦彦军", "start_year": 887, "end_year": 887, "time_original": "光启三年五月甲午", "dynasty": "唐", "description": "秦彦率宣歙军乘竹筏沿江而下，赵晖在上元截击，秦彦军损失惨重。", "phases": [], "location_name": "上元、长江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fe2660f2-1d3b-5819-9f73-27bf6a74150b"}, {"title": "秦彦入广陵并自署权知淮南节度事", "start_year": 887, "end_year": 887, "time_original": "光启三年五月丙申", "dynasty": "唐", "description": "秦彦入广陵，自称权知淮南节度事，任毕师铎为行军司马、赵锽为宣歙观察使。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "62fc9436-6ddf-5178-b046-f63671413cad"}, {"title": "杨行密围广陵设八寨", "start_year": 887, "end_year": 887, "time_original": "光启三年五月戊戌", "dynasty": "唐", "description": "杨行密率军抵广陵城下，设八寨围守；秦彦闭城自守。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fde5431b-a50b-5e93-94cc-af0973fc81bb"}, {"title": "李昌符与杨守立争道引发交战", "start_year": 887, "end_year": 887, "time_original": "光启三年六月戊申至己酉", "dynasty": "唐", "description": "李昌符与杨守立部下因争道相殴，皇帝遣使劝止未果；己酉李昌符拥兵焚行宫。", "phases": [], "location_name": "行宫", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4dd38500-2b13-5dbe-b9d8-901c8745c38c"}, {"title": "李昌符攻大安门败走陇州", "start_year": 887, "end_year": 887, "time_original": "光启三年六月庚戌", "dynasty": "唐", "description": "李昌符攻大安门，与杨守立军在通衢交战，败后率部逃往陇州；杜让能步入宫中侍驾，韦昭度将家属留在军中以激励士卒。", "phases": [], "location_name": "大安门、陇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6d112772-7d35-515b-881e-a29fcdfb9030"}, {"title": "朝廷命李茂贞讨李昌符", "start_year": 887, "end_year": 887, "time_original": "光启三年六月壬子", "dynasty": "唐", "description": "朝廷任李茂贞为陇州招讨使，命其讨李昌符。", "phases": [], "location_name": "陇州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "58af3218-3e25-5c1a-b0cf-4c74cfd3fa84"}]'::jsonb)
